for (Order savedOrder : savedOrders) {
        OrderStatus oldStatus = savedOrder.getStatus();
        savedOrder.setStatus(OrderStatus.CONFIRMED);
        orderRepository.save(savedOrder);

        // Phát event để Notification Module gửi thông báo cho Buyer & Vendor
        eventPublisher.publishEvent(new OrderConfirmedEvent(
                        savedOrder.getId(), savedOrder.getUserId(), savedOrder.getShopId(),
                        savedOrder.getPaymentMethod()
                ));
}

for (com.tmt.ecommerce.order.api.dto.DeliveredOrderData orderData : deliveredOrders) {
    // Check if order contains product
    List<Long> variantIdsInOrder = orderData.productVariantIds();
    boolean hasProduct = variantIdsInOrder.stream()
            .map(productInternalService::getProductIdByVariantId)
            .anyMatch(pid -> pid != null && pid.equals(productId));

    if (hasProduct) {
        // Check if already reviewed
        if (!reviewRepository.existsByUserIdAndOrderIdAndProductId(userId, orderData.orderId(), productId)) {
            eligibleOrderIds.add(orderData.orderId());
        }
    }
}

