for (CartItem item : cart.getItems()) {
    ProductVariantInfoDto variantInfo = productInternalService.getVariantInfo(item.getProductVariantId());

    BigDecimal subTotal = variantInfo.price().multiply(BigDecimal.valueOf(item.getQuantity()));
    boolean isAvailable = "ACTIVE".equals(variantInfo.status()) && variantInfo.stockQuantity() >= item.getQuantity();

    internalDtos.add(new CartItemInternalDto(
            item.getId(),
            variantInfo.variantId(),
            variantInfo.shopId(),
            variantInfo.productName(),
            variantInfo.price(),
            item.getQuantity(),
            subTotal,
            isAvailable
    ));
}

for (CartItem item : cart.getItems()) {
    // Lấy data real-time từ module Product
    ProductVariantInfoDto variantInfo = productInternalService.getVariantInfo(item.getProductVariantId());

    // Tính thành tiền của từng món (Dùng hàm .multiply() của BigDecimal)
    BigDecimal subTotal = variantInfo.price().multiply(BigDecimal.valueOf(item.getQuantity()));

    // Kiểm tra trạng thái khả dụng
    boolean isAvailable = "ACTIVE".equals(variantInfo.status()) && variantInfo.stockQuantity() >= item.getQuantity();

    if (isAvailable) {
        totalAmount = totalAmount.add(subTotal);
    }

    itemResponses.add(new CartItemResponse(
            item.getId(),
            variantInfo.variantId(),
            variantInfo.shopId(), // THÊM TRƯỜNG NÀY ĐỂ MAP VỚI RECORD
            variantInfo.productName(),
            variantInfo.sku(),
            variantInfo.price(),
            item.getQuantity(),
            subTotal,
            variantInfo.thumbnailUrl(),
            variantInfo.attributes(),
            isAvailable
    ));
}

for (ProductVariantUpdateRequest vReq : request.variants()) {
    if (vReq.id() == null) {
        ProductVariant newVariant = ProductVariant.builder()
                .product(product)
                .sku(vReq.sku())
                .price(vReq.price())
                .stockQuantity(vReq.stockQuantity())
                .attributes(vReq.attributes())
                .status(ProductStatus.ACTIVE)
                .build();
        product.getVariants().add(newVariant);
    } else {
        product.getVariants().stream()
                .filter(v -> v.getId().equals(vReq.id()))
                .findFirst()
                .ifPresent(v -> {
                    v.setSku(vReq.sku());
                    v.setPrice(vReq.price());
                    v.setStockQuantity(vReq.stockQuantity());
                    v.setAttributes(vReq.attributes());
                });
    }
}

for (int i = 0; i < request.images().size(); i++) {
    ProductImageUpdateRequest imgReq = request.images().get(i);
    if (imgReq.id() == null) {
        ProductImage newImage = ProductImage.builder()
                .product(product)
                .imageUrl(imgReq.imageUrl())
                .publicId(imgReq.publicId())
                .isThumbnail(Boolean.TRUE.equals(imgReq.isThumbnail()))
                .sortOrder(i)
                .build();
        product.getImages().add(newImage);
    } else {
        final int finalI = i;
        product.getImages().stream()
                .filter(img -> img.getId().equals(imgReq.id()))
                .findFirst()
                .ifPresent(img -> {
                    img.setImageUrl(imgReq.imageUrl());
                    if (imgReq.publicId() != null && !imgReq.publicId().isBlank()) {
                        img.setPublicId(imgReq.publicId());
                    }
                    img.setThumbnail(Boolean.TRUE.equals(imgReq.isThumbnail()));
                    img.setSortOrder(finalI);
                });
    }
}
